page.script:
// 触发事件
function CrrHandler(t) {
	// 保存事件
	if (t.id == "itemSave") {
		if (Ext.getCmp('priceSchemeItemForm').getForm().isValidCux()) {
			var data = Ext.getCmp("priceSchemeItemForm").getForm().getValues();
			var panel = Ext.getCmp('priceSchemeItemList');
			var panelForm = Ext.getCmp('priceSchemeForm').getForm();
			data.schemeNo = panelForm.findField("schemeNo").getValue();
			data.schemeItemNo = data.schemeNo + (panel.operateArray.length + 1).toString().padStart(4, '0');
			setArrayData(panel, [data]);
			panel.getStore().load();
			priceSchemeItemFormWin.close();
		}
	}
}
// 提货地档案列表
function chooseDeliveryPlace() {
	var data = {confirm: "deliveryPlaceConfirm"};
	handleRoute("ChooseDeliveryPlace", data);
}
// 提货地档案确定事件
function deliveryPlaceConfirm(data) {
	var form = Ext.getCmp("priceSchemeItemForm").getForm();
	form.findField("deliveryPlaceNo").setValue(data.deliveryPlaceNo);
	form.findField("deliveryPlaceName").setValue(data.deliveryPlaceName);
	form.findField("deliveryPlaceClassNo").setValue(data.deliveryPlaceClassNo);
	form.findField("deliveryPlaceClassName").setValue(data.deliveryPlaceClassName);
}
// 销售区域列表
function chooseSalesArea() {
	var data = {confirm: "salesAreaConfirm"};
	handleRoute("ChooseSalesArea", data);
}
// 销售区域确定事件
function salesAreaConfirm(data) {
	var form = Ext.getCmp("priceSchemeItemForm").getForm();
	form.findField("areaNo").setValue(data.areaNo);
	form.findField("areaName").setValue(data.areaName);
}
